<?php

# @autogenerated
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityRolesRoleVO;
use Civi\Lughauth\Features\Access\Role\Domain\RoleRef;

final class PlatformIdentityRolesRoleVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = new RoleRef('one');
        $ref = PlatformIdentityRolesRoleVO::from($value);
        $this->assertEquals(new RoleRef('one'), $ref->value());
        $other = PlatformIdentityRolesRoleVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = PlatformIdentityRolesRoleVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = PlatformIdentityRolesRoleVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
}
